package solution

import (
	"strconv"
	"strings"
)

func parse(v string) [3]int {
	v = strings.TrimPrefix(v, "v")
	p := strings.Split(v, ".")
	var out [3]int
	for i := 0; i < 3 && i < len(p); i++ {
		n, _ := strconv.Atoi(p[i])
		out[i] = n
	}
	return out
}

// higher returns the larger of two semver strings.
func higher(a, b string) string {
	pa, pb := parse(a), parse(b)
	for i := 0; i < 3; i++ {
		if pa[i] != pb[i] {
			if pa[i] > pb[i] {
				return a
			}
			return b
		}
	}
	return a // equal: either is fine
}

// MergeMVS folds a list of (module, requiredMinVersion) requirements into the
// per-module maximum — the version MVS would select.
func MergeMVS(reqs []struct{ Module, Version string }) map[string]string {
	sel := make(map[string]string, len(reqs))
	for _, r := range reqs {
		if cur, ok := sel[r.Module]; ok {
			sel[r.Module] = higher(cur, r.Version) // keep the higher minimum
		} else {
			sel[r.Module] = r.Version
		}
	}
	return sel
}

package solution

import (
	"strconv"
	"strings"
)

// MajorFromPath returns the major version encoded in a module path.
// A trailing /vN (N>=2) yields (N, true); any other path yields (1, false).
func MajorFromPath(modulePath string) (int, bool) {
	idx := strings.LastIndex(modulePath, "/")
	if idx < 0 || idx == len(modulePath)-1 {
		return 1, false // no segments, or trailing slash
	}
	last := modulePath[idx+1:]
	if len(last) < 2 || last[0] != 'v' {
		return 1, false // not a v-segment
	}
	num := last[1:]
	if num[0] == '0' { // no leading zero (v01 is invalid)
		return 1, false
	}
	for _, r := range num {
		if r < '0' || r > '9' { // 'vinyl' fails here
			return 1, false
		}
	}
	n, err := strconv.Atoi(num)
	if err != nil || n < 2 { // v0/v1 are never in the path
		return 1, false
	}
	return n, true
}
